package com.example.bikerental; import jakarta.persistence.*; import java.time.LocalDateTime; @Entity @Table(name="favorites",uniqueConstraints=@UniqueConstraint(columnNames={"username","bike_id"})) public class Favorite { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private String username; @ManyToOne(optional=false) private Bike bike; private LocalDateTime createdAt=LocalDateTime.now(); public Favorite(){} public Favorite(String u,Bike b){username=u;bike=b;} public Long getId(){return id;} public String getUsername(){return username;} public Bike getBike(){return bike;} public LocalDateTime getCreatedAt(){return createdAt;} }